create extension if not exists pgcrypto;
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
create type public.staff_role as enum ('admin','employee');
create type public.account_status as enum ('open','paying','closed');
create type public.order_status as enum ('pending','taken','done','cancelled');
create table public.staff (user_id uuid primary key references auth.users(id), role public.staff_role not null, active boolean not null default true, created_at timestamptz not null default now());
create table public.customers (id uuid primary key default gen_random_uuid(), name text not null check (length(trim(name)) between 1 and 120), phone text, created_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null unique);
create table public.products (id uuid primary key default gen_random_uuid(), category_id uuid not null references public.categories(id), name text not null, price_cop bigint not null check (price_cop >= 0), active boolean not null default true, unique(category_id,name));
create table public.shifts (id uuid primary key default gen_random_uuid(), opened_at timestamptz not null default now(), closed_at timestamptz, opened_by uuid not null references public.staff(user_id), check (closed_at is null or closed_at >= opened_at));
create table public.accounts (id uuid primary key default gen_random_uuid(), shift_id uuid not null references public.shifts(id), customer_id uuid references public.customers(id), guest_name text, status public.account_status not null default 'open', opened_at timestamptz not null default now(), closed_at timestamptz, opened_by uuid not null references public.staff(user_id), check ((customer_id is null) <> (guest_name is null)));
create unique index one_open_account_per_customer on public.accounts(customer_id) where status <> 'closed' and customer_id is not null;
create index accounts_shift_status on public.accounts(shift_id,status);
create table public.account_access (account_id uuid not null references public.accounts(id), user_id uuid not null references auth.users(id), created_at timestamptz not null default now(), primary key(account_id,user_id));
create table private.link_codes (id uuid primary key default gen_random_uuid(), account_id uuid not null references public.accounts(id), code_hash bytea not null unique, expires_at timestamptz not null, used_at timestamptz, attempts int not null default 0 check (attempts between 0 and 5));
create table public.orders (id uuid primary key default gen_random_uuid(), account_id uuid not null references public.accounts(id), requested_by uuid not null references auth.users(id), idempotency_key uuid not null, status public.order_status not null default 'pending', created_at timestamptz not null default now(), taken_by uuid references public.staff(user_id), unique(requested_by,idempotency_key));
create index orders_account_status on public.orders(account_id,status);
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), product_id uuid not null references public.products(id), quantity int not null check (quantity between 1 and 100), delivered_quantity int not null default 0 check (delivered_quantity >= 0 and delivered_quantity <= quantity));
create table public.deliveries (id uuid primary key default gen_random_uuid(), account_id uuid not null references public.accounts(id), order_item_id uuid references public.order_items(id), product_id uuid not null references public.products(id), quantity int not null check (quantity between 1 and 100), unit_price_cop bigint not null check (unit_price_cop >= 0), delivered_by uuid not null references public.staff(user_id), delivered_at timestamptz not null default now(), idempotency_key uuid not null, unique(delivered_by,idempotency_key));
create index deliveries_account on public.deliveries(account_id);
create table public.payment_requests (id uuid primary key default gen_random_uuid(), account_id uuid not null references public.accounts(id), requested_by uuid not null references auth.users(id), requested_at timestamptz not null default now(), taken_by uuid references public.staff(user_id), cancelled_at timestamptz);
create unique index one_payment_request on public.payment_requests(account_id) where cancelled_at is null;
create table public.payments (id uuid primary key default gen_random_uuid(), account_id uuid not null unique references public.accounts(id), amount_cop bigint not null check (amount_cop >= 0), received_by uuid not null references public.staff(user_id), received_at timestamptz not null default now());
create table private.audit (id uuid primary key default gen_random_uuid(), actor uuid, action text not null, entity_id uuid not null, details jsonb not null default '{}', created_at timestamptz not null default now());
create function private.is_staff() returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.staff where user_id=auth.uid() and active) $$;
create function private.is_admin() returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.staff where user_id=auth.uid() and active and role='admin') $$;
create function private.can_access(p_account uuid) returns boolean language sql stable security definer set search_path = '' as $$ select private.is_staff() or exists(select 1 from public.account_access where account_id=p_account and user_id=auth.uid()) $$;
revoke all on all functions in schema private from public,anon,authenticated;
grant usage on schema private to authenticated;
grant execute on function private.is_staff(),private.is_admin(),private.can_access(uuid) to authenticated;
do $$ declare t text; begin foreach t in array array['staff','customers','categories','products','shifts','accounts','account_access','orders','order_items','deliveries','payment_requests','payments'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon, authenticated',t); end loop; end $$;
grant select on public.categories,public.products,public.accounts,public.orders,public.order_items,public.deliveries,public.payment_requests,public.payments to authenticated;
grant select on public.customers,public.shifts,public.staff to authenticated;
create policy products_read on public.products for select to authenticated using (active or private.is_staff());
create policy categories_read on public.categories for select to authenticated using (true);
create policy accounts_read on public.accounts for select to authenticated using (private.can_access(id));
create policy orders_read on public.orders for select to authenticated using (private.can_access(account_id));
create policy order_items_read on public.order_items for select to authenticated using (exists(select 1 from public.orders o where o.id=order_id and private.can_access(o.account_id)));
create policy deliveries_read on public.deliveries for select to authenticated using (private.can_access(account_id));
create policy requests_read on public.payment_requests for select to authenticated using (private.can_access(account_id));
create policy payments_read on public.payments for select to authenticated using (private.can_access(account_id));
create policy customers_staff on public.customers for select to authenticated using (private.is_staff());
create policy shifts_staff on public.shifts for select to authenticated using (private.is_staff());
create policy staff_self on public.staff for select to authenticated using (user_id=auth.uid() or private.is_admin());
